import{_ as t,a,o as r,a2 as o}from"./chunks/framework.DCcmcJcL.js";const p=JSON.parse('{"title":"Store Setup Checklist","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/store-setup-checklist.md","filePath":"getting-started/store-setup-checklist.md","lastUpdated":1789441803000}'),s={name:"getting-started/store-setup-checklist.md"};function n(h,e,i,d,c,l){return r(),a("div",null,e[0]||(e[0]=[o('<h1 id="store-setup-checklist" tabindex="-1">Store Setup Checklist <a class="header-anchor" href="#store-setup-checklist" aria-label="Permalink to &quot;Store Setup Checklist&quot;">​</a></h1><p>A new Bagisto store already has a <strong>Default</strong> channel, a <strong>Default</strong> inventory source, the <strong>Administrator</strong> role, and the languages and currencies chosen when Bagisto was installed. Work through these steps in order to turn it into a store that&#39;s ready for its first order. Each step links to the page with the details.</p><div class="tip custom-block"><p class="custom-block-title">Hide the storefront while you set up</p><p>Turn on <a href="./../settings/channels.html#maintenance-mode">maintenance mode</a> for your channel and add your own IP address to <strong>Allowed IPs</strong>, so only you can see the storefront until it&#39;s ready.</p></div><h2 id="set-up-your-store" tabindex="-1">Set up your store <a class="header-anchor" href="#set-up-your-store" aria-label="Permalink to &quot;Set up your store&quot;">​</a></h2><h3 id="_1-secure-your-account" tabindex="-1">1. Secure your account <a class="header-anchor" href="#_1-secure-your-account" aria-label="Permalink to &quot;1. Secure your account&quot;">​</a></h3><p>Update your name, email address and password in <strong>My Account</strong>, and turn on two-factor authentication. See <a href="./admin-panel.html#update-your-account">Admin Panel</a> and <a href="./../authentication/2fa-authentication.html">Two-Factor Authentication</a>.</p><h3 id="_2-set-up-your-channel-and-languages" tabindex="-1">2. Set up your channel and languages <a class="header-anchor" href="#_2-set-up-your-channel-and-languages" aria-label="Permalink to &quot;2. Set up your channel and languages&quot;">​</a></h3><p>Check the <strong>Default</strong> channel&#39;s name, hostname, logo, favicon and home page SEO. Add any language you sell in that isn&#39;t there yet, select it in the channel, and choose the language the storefront opens in. See <a href="./../settings/channels.html">Channels</a> and <a href="./../settings/locales.html">Locales</a>.</p><h3 id="_3-set-up-currencies-and-exchange-rates" tabindex="-1">3. Set up currencies and exchange rates <a class="header-anchor" href="#_3-set-up-currencies-and-exchange-rates" aria-label="Permalink to &quot;3. Set up currencies and exchange rates&quot;">​</a></h3><p>Product prices are entered in your base currency. Add each other currency shoppers can choose, select it in the channel, and give it an exchange rate, by hand or from an exchange rate service. See <a href="./../settings/currencies.html">Currencies</a> and <a href="./../settings/exchange-rates.html">Exchange Rates</a>.</p><h3 id="_4-set-up-taxes" tabindex="-1">4. Set up taxes <a class="header-anchor" href="#_4-set-up-taxes" aria-label="Permalink to &quot;4. Set up taxes&quot;">​</a></h3><p>Create a tax rate for each place you charge tax, and group the rates in a tax category. Then choose which address tax is based on, whether prices include tax, and the default tax category. See <a href="./../settings/taxes.html">Taxes</a> and <a href="./../configure/taxes.html">Configure &gt;&gt; Sales &gt;&gt; Taxes</a>.</p><h3 id="_5-add-your-inventory-sources" tabindex="-1">5. Add your inventory sources <a class="header-anchor" href="#_5-add-your-inventory-sources" aria-label="Permalink to &quot;5. Add your inventory sources&quot;">​</a></h3><p>If you keep stock in more than one place, add each warehouse or shop as an inventory source, and select it in the channel. See <a href="./../settings/inventory-source.html">Inventory Sources</a>.</p><h3 id="_6-choose-shipping-and-payment-methods" tabindex="-1">6. Choose shipping and payment methods <a class="header-anchor" href="#_6-choose-shipping-and-payment-methods" aria-label="Permalink to &quot;6. Choose shipping and payment methods&quot;">​</a></h3><p>Check your shipping settings, switch on the shipping methods you offer and set their prices, then switch on the payment methods customers can use. See <a href="./../configure/shipping.html">Shipping Settings</a>, <a href="./../shipping-method/shipping-methods.html">Shipping Methods</a> and <a href="./../payment-method/payment-methods.html">Payment Methods</a>.</p><h3 id="_7-add-categories-and-products" tabindex="-1">7. Add categories and products <a class="header-anchor" href="#_7-add-categories-and-products" aria-label="Permalink to &quot;7. Add categories and products&quot;">​</a></h3><p>Create your categories under the channel&#39;s root category, then add your products one by one or import them from a file. Give each product its channels, tax category and stock. See <a href="./../category/create-category.html">Categories</a>, <a href="./../product-types/products.html">Products</a> and <a href="./../settings/data-transfer.html">Data Transfer</a>.</p><h3 id="_8-design-your-storefront" tabindex="-1">8. Design your storefront <a class="header-anchor" href="#_8-design-your-storefront" aria-label="Permalink to &quot;8. Design your storefront&quot;">​</a></h3><p>Choose the theme for your channel and build its pages from sections. Nothing changes on the storefront until you publish. See <a href="./../appearance/themes.html">Themes &amp; Sections</a>.</p><h3 id="_9-set-up-store-email" tabindex="-1">9. Set up store email <a class="header-anchor" href="#_9-set-up-store-email" aria-label="Permalink to &quot;9. Set up store email&quot;">​</a></h3><p>Choose how your store sends email, enter the sender&#39;s name and email address, and choose which emails are sent. Without this, customers don&#39;t get order emails, and admins don&#39;t get password reset links or two-factor backup codes. See <a href="./../configure/email-settings.html">Email Settings</a> and <a href="./../configure/notifications.html">Notifications</a>.</p><h3 id="_10-ask-for-scheduled-tasks-and-the-queue-worker" tabindex="-1">10. Ask for scheduled tasks and the queue worker <a class="header-anchor" href="#_10-ask-for-scheduled-tasks-and-the-queue-worker" aria-label="Permalink to &quot;10. Ask for scheduled tasks and the queue worker&quot;">​</a></h3><p>Some work runs on a timetable or in the background, such as nightly catalog rule prices, campaigns and queued emails. Ask your developer or hosting provider to set up the scheduler and, if your store uses a queue, a queue worker. See <a href="./scheduled-tasks.html">Scheduled Tasks</a>.</p><h3 id="_11-place-a-test-order" tabindex="-1">11. Place a test order <a class="header-anchor" href="#_11-place-a-test-order" aria-label="Permalink to &quot;11. Place a test order&quot;">​</a></h3><ol><li>Click <strong>Visit Shop</strong> in the header to open your storefront.</li><li>Add a product to the cart.</li><li>Go to the checkout.</li><li>Choose one of your shipping methods and payment methods.</li><li>Place the order.</li><li>In the admin panel, go to <strong>Sales &gt;&gt; Orders</strong>.</li><li>Open the order.</li><li>Check the prices, tax and shipping.</li><li>Create an invoice for the order.</li><li>Create a shipment for the order.</li></ol><p>See <a href="./../orders/orders.html">Orders</a>, <a href="./../orders/create-invoice.html">Create Invoice</a> and <a href="./../orders/create-shipment.html">Create Shipment</a>. When everything works, switch maintenance mode off to open your store.</p><h2 id="keep-going" tabindex="-1">Keep going <a class="header-anchor" href="#keep-going" aria-label="Permalink to &quot;Keep going&quot;">​</a></h2><ul><li><strong>Add your team</strong>: create a role for each kind of work, then a user for each person. See <a href="./../settings/roles.html">Roles</a> and <a href="./../settings/users.html">Users</a>.</li><li><strong>Write content faster</strong>: draft product content and images with Generative AI (Magic AI). See <a href="./../generative-ai/introduction.html">Generative AI</a>.</li><li><strong>Promote your store</strong>: offer discounts and coupons. See <a href="./../marketing/cart-rules.html">Cart Rules</a> and <a href="./../marketing/catalog-rules.html">Catalog Rules</a>.</li><li><strong>Follow your results</strong>: check the <a href="./dashboard.html">Dashboard</a> and <a href="./../reporting/sales-report.html">Reporting</a>.</li></ul>',29)]))}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
